-- Per-license entitlement projection and correct expired-license aggregation.
create or replace function public.mvp_license_entitled(p_user uuid,p_license uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from license_activations a join licenses l on l.id=a.license_id join subscriptions s on s.activation_id=a.id left join reseller_access r on r.id=l.reseller_access_id where a.user_id=p_user and l.id=p_license and l.status in ('active','redeemed') and s.status='active' and (a.expires_at is null or a.expires_at>now()) and (r.id is null or (case when r.status='active' then r.ends_at+interval '15 days' else coalesce(r.grace_until,r.updated_at+interval '15 days') end)>now()));$$;
create or replace function public.mvp_metrics(p_user uuid) returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('users',case when mvp_is_admin(p_user) then (select count(*) from user_profiles) else 0 end,'licenses',(select count(*) from licenses where mvp_is_admin(p_user) or creator_id=p_user),'active',(select count(*) from licenses l where (mvp_is_admin(p_user) or l.creator_id=p_user) and exists(select 1 from license_activations a where a.license_id=l.id and mvp_license_entitled(a.user_id,l.id))),'banned',(select count(*) from licenses where (mvp_is_admin(p_user) or creator_id=p_user) and status='banned'),'expired',(select count(*) from licenses l where (mvp_is_admin(p_user) or l.creator_id=p_user) and (l.status='expired' or (l.status='redeemed' and exists(select 1 from license_activations a where a.license_id=l.id) and not exists(select 1 from license_activations a where a.license_id=l.id and (a.expires_at is null or a.expires_at>now()))))),'unusedUsers',case when mvp_is_admin(p_user) then (select count(*) from user_profiles u where not exists(select 1 from license_activations where user_id=u.id)) else 0 end);$$;
revoke all on function public.mvp_license_entitled(uuid,uuid) from public,anon,authenticated;
grant execute on function public.mvp_license_entitled(uuid,uuid) to service_role;
